import sys

class TreeNode:
    __slots__ = ('left', 'right')  # reduces memory usage
    def __init__(self, left=None, right=None):
        self.left = left
        self.right = right

def bottom_up_tree(depth):
    if depth > 0:
        left = bottom_up_tree(depth - 1)
        right = bottom_up_tree(depth - 1)
        return TreeNode(left, right)
    else:
        return TreeNode()

def item_check(node):
    if node.left is None and node.right is None:
        return 1
    return 1 + item_check(node.left) + item_check(node.right)

class Solution:
    def binaryTrees(self, N: int) -> None:
        if N < 0:
            return

        stretch_depth = N + 1
        # Stretch tree
        stretch_tree = bottom_up_tree(stretch_depth)
        print(f"stretch tree of depth {stretch_depth}\t check: {item_check(stretch_tree)}")

        # Long-lived tree
        long_lived_tree = bottom_up_tree(N)

        depths = list(range(4, N+1, 2))
        for depth in depths:
            iterations = 2 ** (N - depth + 4)
            check = 0
            for _ in range(iterations):
                t = bottom_up_tree(depth)
                check += item_check(t)
            print(f"{iterations}\t trees of depth {depth}\t check: {check}")

        print(f"long lived tree of depth {N}\t check: {item_check(long_lived_tree)}")

if __name__ == "__main__":
